#!/usr/bin/env node
/**
 * Build the playable route (public/data/routes/west-sussex/) from the cached OpenStreetMap data
 * and terrain tiles. Run tools/fetch-osm.mjs and tools/fetch-terrain.mjs first.
 *
 *   node tools/build-route.mjs
 *
 * Everything the real data doesn't tell us (signal positions, exact gradients, stop markers) is
 * generated by rules written down in docs/ASSUMPTIONS.md. Data © OpenStreetMap contributors (ODbL).
 */
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';
import { area, cumulative, dist, inPolygon, makeProjection, pointAlong, projectOnto, simplify } from './lib/geo.mjs';
import { RailGraph } from './lib/railgraph.mjs';
import { Dem } from './lib/dem.mjs';
import { TERRAIN_ZOOM } from './fetch-terrain.mjs';
import { timetableServices } from './lib/timetable.mjs';

const here = (/** @type {string} */ p) => fileURLToPath(new URL(p, import.meta.url));
const CACHE = here('./research/osm-cache');
const TERRAIN = here('./research/terrain-cache');
const OUT = here('../public/data/routes/west-sussex');
const RESEARCH = JSON.parse(readFileSync(here('./research/route-features.json'), 'utf8'));

const ORIGIN = { lat: 50.83188, lon: -0.78185 }; // Chichester station
const proj = makeProjection(ORIGIN.lat, ORIGIN.lon);
const P = (/** @type {number} */ lat, /** @type {number} */ lon) => proj.project(lat, lon);
const dem = new Dem(TERRAIN, TERRAIN_ZOOM);
const STEP = 10; // alignment point spacing (m)
const TRACK_HALF = 1.7;

const STATIONS = [
  { id: 'CCH', name: 'Chichester', lat: 50.83188, lon: -0.78185, line: 'main' },
  { id: 'BAA', name: 'Barnham', lat: 50.83074, lon: -0.6402, line: 'main' },
  { id: 'FOD', name: 'Ford', lat: 50.82936, lon: -0.5783, line: 'main' },
  { id: 'ARU', name: 'Arundel', lat: 50.84801, lon: -0.54627, line: 'main' },
  { id: 'AMY', name: 'Amberley', lat: 50.89642, lon: -0.54203, line: 'main' },
  { id: 'BOG', name: 'Bognor Regis', lat: 50.7866, lon: -0.6764, line: 'bognor' },
  { id: 'LIT', name: 'Littlehampton', lat: 50.81017, lon: -0.54626, line: 'littlehampton' },
];

// ── load cached OSM layers ───────────────────────────────────────────────────

/** @param {string} prefix */
function layer(prefix) {
  /** @type {Map<number, any>} */
  const out = new Map();
  for (const f of readdirSync(CACHE).filter((n) => n.startsWith(`${prefix}-`) || n === `${prefix}.json`)) {
    for (const e of JSON.parse(readFileSync(join(CACHE, f), 'utf8')).elements) out.set(e.type + e.id, e);
  }
  if (!out.size) console.warn(`  (no cached "${prefix}" data: that layer will be skipped)`);
  return [...out.values()];
}

const rail = layer('rail');
const graph = new RailGraph(rail, proj.project);
console.log(`rail: ${graph.ways.length} ways, ${graph.nodes.size} nodes`);

// ── lines ────────────────────────────────────────────────────────────────────

/** Main line: Chichester (west of the station) → Arundel Junction → Amberley (north of the station). */
const mainNodes = graph.path(graph.nearest(P(50.833, -0.788)), graph.nearest(P(50.9065, -0.5437)));
const mainPts = graph.centreline(graph.xy(mainNodes), STEP);
const mainCum = cumulative(mainPts);
const mainSet = new Set(mainNodes);

/**
 * A branch from its far end back to the main line; cut where it meets the main centreline.
 * @param {[number, number]} far
 * @param {[number, number]} via a point on the main line beyond the junction
 * @param {number} [maxLength] trim the branch to this length (m)
 */
function branch(far, via, maxLength = Infinity) {
  const path = graph.xy(graph.path(graph.nearest(far), graph.nearest(via, (id) => mainSet.has(id))));
  const k = path.findIndex((p) => projectOnto(mainPts, mainCum, p).d < 5);
  const junction = projectOnto(mainPts, mainCum, path[k]);
  // Outward from the junction, starting exactly on the main centreline.
  const start = pointAlong(mainPts, mainCum, junction.s).p;
  let pts = graph.centreline([start, ...path.slice(0, k).reverse()], STEP);
  pts[0] = start;
  const cum = cumulative(pts);
  if (cum[cum.length - 1] > maxLength) pts = pts.filter((_, i) => cum[i] <= maxLength);
  return { junctionS: junction.s, pts };
}

const bognor = branch(P(50.7866, -0.6764), P(50.8307, -0.638));
const lhamp = branch(P(50.8102, -0.5461), P(50.829, -0.58));
const coast = branch(P(50.8255, -0.54), P(50.829, -0.58), 1500);
console.log(`main ${Math.round(mainCum.at(-1))} m; junctions: Barnham ${Math.round(bognor.junctionS)}, Ford ${Math.round(lhamp.junctionS)}, Arundel ${Math.round(coast.junctionS)}`);

/** @type {Record<string, { pts: [number, number][], cum: number[] }>} */
const geo = {
  main: { pts: mainPts, cum: mainCum },
  bognor: { pts: bognor.pts, cum: cumulative(bognor.pts) },
  littlehampton: { pts: lhamp.pts, cum: cumulative(lhamp.pts) },
  coast: { pts: coast.pts, cum: cumulative(coast.pts) },
};
const lengthOf = (/** @type {string} */ id) => geo[id].cum[geo[id].cum.length - 1];

/** Which line is a point on (nearest within `maxD`), and where. */
function locate(/** @type {[number, number]} */ q, maxD = 20, only = Object.keys(geo)) {
  let best = null;
  for (const id of only) {
    const r = projectOnto(geo[id].pts, geo[id].cum, q);
    // Don't snap to the first metres of a branch: that's really the main line.
    if (id !== 'main' && r.s < 30) continue;
    if (r.d <= maxD && (!best || r.d < best.d)) best = { line: id, ...r };
  }
  return best;
}

// ── structures, speeds, heights ──────────────────────────────────────────────

/** Bridges and tunnels along each line, from the rail ways' tags. */
function structures(/** @type {string} */ lineId) {
  /** @type {{ type: 'bridge' | 'tunnel', from: number, to: number, name?: string }[]} */
  const out = [];
  const g = geo[lineId];
  for (const w of graph.ways) {
    const type = w.tags.tunnel ? 'tunnel' : w.tags.bridge ? 'bridge' : null;
    if (!type) continue;
    const ends = [w.xy[0], w.xy[w.xy.length - 1]].map((p) => projectOnto(g.pts, g.cum, p));
    if (ends.some((e) => e.d > 6)) continue;
    const from = Math.min(ends[0].s, ends[1].s);
    const to = Math.max(ends[0].s, ends[1].s);
    if (to - from < 2) continue;
    const overlap = out.find((s) => s.type === type && s.from <= to + 5 && s.to >= from - 5);
    if (overlap) {
      overlap.from = Math.min(overlap.from, from);
      overlap.to = Math.max(overlap.to, to);
    } else {
      const name = type === 'tunnel' ? w.tags['tunnel:name'] ?? w.tags.name : w.tags['bridge:name'];
      out.push({ type, from, to, ...(name ? { name } : {}) });
    }
  }
  return out.sort((a, b) => a.from - b.from).map((s) => ({ ...s, from: round(s.from), to: round(s.to) }));
}

/** Speed limits from OSM maxspeed: the fastest running line near each point (crossovers are slower). */
function speedLimits(/** @type {string} */ lineId) {
  const g = geo[lineId];
  /** @type {number[]} */
  const mph = [];
  for (let s = 0; s <= lengthOf(lineId); s += 20) {
    const { p } = pointAlong(g.pts, g.cum, s);
    let best = 0;
    for (const [way] of graph.waysNear(p, 4.5)) {
      const v = parseInt(way.tags.maxspeed ?? '', 10);
      if (v > best) best = v;
    }
    mph.push(best || mph[mph.length - 1] || 60);
  }
  // Runs of equal limits; drop blips shorter than 150 m.
  /** @type {{ from: number, to: number, mph: number }[]} */
  let segs = [];
  mph.forEach((v, i) => {
    const s = i * 20;
    const last = segs[segs.length - 1];
    if (last && last.mph === v) last.to = s + 20;
    else segs.push({ from: s, to: s + 20, mph: v });
  });
  // Absorb short blips into the previous segment, then merge equal neighbours.
  for (let pass = 0; pass < 3; pass++) {
    /** @type {{ from: number, to: number, mph: number }[]} */
    const kept = [];
    for (const seg of segs) {
      const last = kept[kept.length - 1];
      if (last && (seg.to - seg.from < 150 || last.mph === seg.mph)) last.to = seg.to;
      else kept.push({ ...seg });
    }
    segs = kept;
  }
  const len = lengthOf(lineId);
  segs[segs.length - 1].to = len;
  return segs.map((s) => ({ from: round(s.from), to: round(Math.min(len, s.to)), mph: s.mph }));
}

/**
 * Gradient profile from the terrain data. The terrain model is a surface model (trees and
 * buildings show up), so take a low percentile over a window, bridge over dips at bridges and
 * humps at tunnels, then smooth hard and fit 400 m steps.
 * @param {string} lineId
 * @param {number} startElevation for branches: the main line height at the junction
 */
function gradients(lineId, startElevation) {
  const g = geo[lineId];
  const len = lengthOf(lineId);
  const step = 25;
  /** @type {number[]} */
  let h = [];
  for (let s = 0; s <= len; s += step) {
    const { p } = pointAlong(g.pts, g.cum, s);
    const [lat, lon] = proj.unproject(p[0], p[1]);
    h.push(dem.height(lat, lon) ?? h[h.length - 1] ?? 5);
  }
  // Low percentile over ±75 m strips out trees and houses.
  h = h.map((_, i) => {
    const win = h.slice(Math.max(0, i - 3), i + 4).sort((a, b) => a - b);
    return win[Math.floor(win.length * 0.25)];
  });
  // Straight lines across bridges and tunnels (+ approaches).
  for (const st of structures(lineId)) {
    const a = Math.max(0, Math.floor((st.from - 80) / step));
    const b = Math.min(h.length - 1, Math.ceil((st.to + 80) / step));
    for (let i = a + 1; i < b; i++) h[i] = h[a] + ((h[b] - h[a]) * (i - a)) / (b - a);
  }
  // Heavy smoothing (±400 m).
  const k = Math.round(400 / step);
  h = h.map((_, i) => {
    const win = h.slice(Math.max(0, i - k), i + k + 1);
    return win.reduce((x, y) => x + y, 0) / win.length;
  });
  const offset = startElevation === undefined ? 0 : startElevation - h[0];
  h = h.map((v) => Math.max(1.5, v + offset));
  /** @type {{ from: number, to: number, permille: number }[]} */
  const segs = [];
  const SEG = 400;
  let elev = h[0];
  for (let s = 0; s < len; s += SEG) {
    const to = Math.min(len, s + SEG);
    const target = h[Math.min(h.length - 1, Math.round(to / step))];
    let permille = Math.round(((target - elev) / (to - s)) * 1000 * 2) / 2;
    permille = Math.max(-12, Math.min(12, permille)); // 1 in 83 is plenty steep for this line
    elev += (permille * (to - s)) / 1000;
    const last = segs[segs.length - 1];
    if (last && last.permille === permille) last.to = round(to);
    else segs.push({ from: round(s), to: round(to), permille });
  }
  return { start: round(h[0]), segs };
}

const round = (/** @type {number} */ v) => Math.round(v * 10) / 10;
const elevationAt = (/** @type {{ start: number, segs: { from: number, to: number, permille: number }[] }} */ prof, /** @type {number} */ s) => {
  let e = prof.start;
  for (const seg of prof.segs) {
    if (s <= seg.from) break;
    e += (seg.permille * (Math.min(s, seg.to) - seg.from)) / 1000;
  }
  return e;
};

/**
 * Speeds over the junction turnouts. Sampling OSM near a junction picks up the faster main-line
 * ways alongside, so these come straight from the OSM maxspeed tags on the turnout ways (A: check
 * the Sectional Appendix).
 */
const JUNCTION_SPEEDS = { bognor: { to: 300, mph: 20 }, littlehampton: { to: 300, mph: 40 }, coast: { to: 250, mph: 30 } };

/** @param {string} id @param {{ from: number, to: number, mph: number }[]} segs */
function withJunctionSpeed(id, segs) {
  const j = JUNCTION_SPEEDS[/** @type {keyof typeof JUNCTION_SPEEDS} */ (id)];
  if (!j) return segs;
  const rest = segs
    .map((sg) => ({ ...sg, from: Math.max(sg.from, j.to) }))
    .filter((sg) => sg.to > sg.from);
  return [{ from: 0, to: j.to, mph: j.mph }, ...rest];
}

const mainGrad = gradients('main');
const lineDefs = {
  main: { name: 'Chichester – Ford – Arundel – Amberley (ELR TBH)', speed: speedLimits('main'), grad: mainGrad, ends: { start: 'open', end: 'open' } },
  bognor: { name: 'Barnham Junction – Bognor Regis (ELR BBR)', speed: withJunctionSpeed('bognor', speedLimits('bognor')), grad: gradients('bognor', elevationAt(mainGrad, bognor.junctionS)), ends: { start: 'junction', end: 'buffers' } },
  littlehampton: { name: 'Ford Junction – Littlehampton (ELR FJL / BLI)', speed: withJunctionSpeed('littlehampton', speedLimits('littlehampton')), grad: gradients('littlehampton', elevationAt(mainGrad, lhamp.junctionS)), ends: { start: 'junction', end: 'buffers' } },
  coast: { name: 'Arundel Junction – towards Angmering (ELR BLI)', speed: withJunctionSpeed('coast', speedLimits('coast')), grad: gradients('coast', elevationAt(mainGrad, coast.junctionS)), ends: { start: 'junction', end: 'open' } },
};

/** Most common limit becomes the line speed; the rest are listed. */
function lineSpeedOf(/** @type {{ from: number, to: number, mph: number }[]} */ segs) {
  /** @type {Map<number, number>} */
  const total = new Map();
  for (const s of segs) total.set(s.mph, (total.get(s.mph) ?? 0) + s.to - s.from);
  return [...total.entries()].sort((a, b) => b[1] - a[1])[0][0];
}

const lines = Object.entries(lineDefs).map(([id, d]) => {
  const lineSpeedMph = lineSpeedOf(d.speed);
  return {
    id,
    name: d.name,
    alignment: { points: geo[id].pts.map(([x, y]) => [round(x), round(y)]), startElevationM: d.grad.start },
    lineSpeedMph,
    ends: d.ends,
    tracks:
      id === 'main'
        ? [
            { id: 'UP', name: 'Up Main', offset: -TRACK_HALF, dir: 1, conductorRail: 'right' },
            { id: 'DOWN', name: 'Down Main', offset: TRACK_HALF, dir: -1, conductorRail: 'right' },
          ]
        : [
            { id: 'DOWN', name: 'Down (away from the junction)', offset: -TRACK_HALF, dir: 1, conductorRail: 'right' },
            { id: 'UP', name: 'Up (towards the junction)', offset: TRACK_HALF, dir: -1, conductorRail: 'right' },
          ],
    gradients: d.grad.segs,
    speedLimits: d.speed.filter((s) => s.mph !== lineSpeedMph),
    structures: structures(id),
  };
});

// ── junctions and points ─────────────────────────────────────────────────────

const J = { barnham: round(bognor.junctionS), ford: round(lhamp.junctionS), arundel: round(coast.junctionS) };
const points = [
  { id: 'BJ-D', name: 'Barnham Jn (Down main to Bognor)', junction: 'Barnham Junction', type: 'facing', at: { line: 'main', track: 'DOWN', position: J.barnham }, other: { line: 'bognor', track: 'DOWN', position: 0 } },
  { id: 'BJ-U', name: 'Barnham Jn (Bognor to Up main)', junction: 'Barnham Junction', type: 'trailing', at: { line: 'main', track: 'UP', position: J.barnham }, other: { line: 'bognor', track: 'UP', position: 0 }, crosses: ['main/DOWN'] },
  { id: 'FJ-U', name: 'Ford Jn (Up main to Littlehampton)', junction: 'Ford Junction', type: 'facing', at: { line: 'main', track: 'UP', position: J.ford }, other: { line: 'littlehampton', track: 'DOWN', position: 0 }, crosses: ['main/DOWN'] },
  { id: 'FJ-D', name: 'Ford Jn (Littlehampton to Down main)', junction: 'Ford Junction', type: 'trailing', at: { line: 'main', track: 'DOWN', position: J.ford }, other: { line: 'littlehampton', track: 'UP', position: 0 } },
  { id: 'AJ-U', name: 'Arundel Jn (Up main to the coast line)', junction: 'Arundel Junction', type: 'facing', at: { line: 'main', track: 'UP', position: J.arundel }, other: { line: 'coast', track: 'DOWN', position: 0 }, crosses: ['main/DOWN'] },
  { id: 'AJ-D', name: 'Arundel Jn (coast line to Down main)', junction: 'Arundel Junction', type: 'trailing', at: { line: 'main', track: 'DOWN', position: J.arundel }, other: { line: 'coast', track: 'UP', position: 0 } },
];

// ── stations and platforms ───────────────────────────────────────────────────

const stations = STATIONS.map((st) => {
  const at = locate(P(st.lat, st.lon), 60, [st.line]) ?? { s: 0 };
  return { id: st.id, name: st.name, line: st.line, position: round(at.s) };
});

/** @type {any[]} */
const platforms = [];
const trackOfSide = (/** @type {string} */ line, /** @type {number} */ lateral) => (lateral < 0 ? (line === 'main' ? 'UP' : 'DOWN') : line === 'main' ? 'DOWN' : 'UP');
const dirOf = (/** @type {string} */ line, /** @type {string} */ track) => (line === 'main' ? (track === 'UP' ? 1 : -1) : track === 'DOWN' ? 1 : -1);

for (const e of layer('platforms')) {
  if (!e.geometry) continue;
  const pts = e.geometry.map((/** @type {any} */ g) => P(g.lat, g.lon));
  const hits = pts.map((/** @type {[number, number]} */ p) => locate(p, 25)).filter(Boolean);
  if (hits.length < 2) continue;
  const line = hits[0].line;
  const mine = hits.filter((/** @type {any} */ h) => h.line === line);
  const from = Math.min(...mine.map((/** @type {any} */ h) => h.s));
  const to = Math.max(...mine.map((/** @type {any} */ h) => h.s));
  if (to - from < 60) continue;
  const lateral = mine.reduce((/** @type {number} */ a, /** @type {any} */ h) => a + h.lateral, 0) / mine.length;
  const st = stations.filter((s) => s.line === line).sort((a, b) => Math.abs(a.position - (from + to) / 2) - Math.abs(b.position - (from + to) / 2))[0];
  if (!st || Math.abs(st.position - (from + to) / 2) > 400) continue;
  const track = trackOfSide(line, lateral);
  platforms.push({ station: st.id, line, track, from: round(from), to: round(to), lateral, ref: e.tags?.ref ?? '' });
  if (process.env.DEBUG_PLATFORMS) console.log(`platform ${st.id} ${e.tags?.ref ?? '-'} ${track} ${round(from)}–${round(to)} lateral ${lateral.toFixed(1)}`);
}

// One platform per station per track: the face next to the track (Barnham has a second Down-side
// platform beyond a bay line we don't model), else the longest. Stations without OSM platforms
// get a 240 m one.
/** @type {any[]} */
const chosen = [];
for (const st of stations) {
  for (const track of st.line === 'main' ? ['UP', 'DOWN'] : ['DOWN', 'UP']) {
    const all = platforms.filter((p) => p.station === st.id && p.track === track);
    const longest = Math.max(0, ...all.map((p) => p.to - p.from));
    const options = all.filter((p) => p.to - p.from >= 0.8 * longest).sort((a, b) => Math.abs(a.lateral) - Math.abs(b.lateral));
    let p = options[0];
    if (!p) {
      const len = lengthOf(st.line);
      const terminus = st.line !== 'main';
      const to = terminus ? len - 12 : st.position + 120;
      p = { station: st.id, line: st.line, track, from: round(Math.max(0, to - 240)), to: round(to), ref: '', synthetic: true };
    }
    const dir = dirOf(st.line, track);
    const exitEnd = dir > 0 ? p.to : p.from;
    const len = p.to - p.from;
    // 4-car marker: near the exit end but not right at it (A).
    const back = Math.max(8, Math.min(40, (len - 82) / 3));
    const markers = [4, 8, 12]
      .filter((cars) => cars * 20.4 + 6 <= len)
      .map((cars) => ({ cars, position: round(exitEnd - dir * (cars === 4 ? back : 6)) }));
    chosen.push({
      id: `${st.id}-${track}`,
      station: st.id,
      name: st.name,
      ref: p.ref,
      line: st.line,
      track,
      from: p.from,
      to: p.to,
      side: 'left', // platforms are given to the track on their side of the line, so always the driver's left
      stopMarkers: markers.length ? markers : [{ cars: 4, position: round(exitEnd - dir * 6) }],
      ...(p.synthetic ? { synthetic: true } : {}),
    });
  }
}
console.log(`platforms: ${chosen.map((p) => `${p.id}${p.ref ? ` (${p.ref})` : ''}${p.synthetic ? ' [synthetic]' : ''}`).join(', ')}`);

// ── level crossings ──────────────────────────────────────────────────────────

/** @type {any[]} */
const crossings = [];
{
  const lcEls = layer('crossings');
  const nodes = lcEls.filter((e) => e.type === 'node' && e.tags);
  const ways = lcEls.filter((e) => e.type === 'way');
  /** @type {{ lat: number, lon: number, ids: number[], tags: any }[]} */
  const groups = [];
  for (const n of nodes) {
    const g = groups.find((x) => Math.hypot((x.lat - n.lat) * 111000, (x.lon - n.lon) * 70000) < 25);
    if (g) g.ids.push(n.id);
    else groups.push({ lat: n.lat, lon: n.lon, ids: [n.id], tags: n.tags });
  }
  const source = groups.length
    ? groups.map((g) => {
        const road = ways.find((w) => g.ids.some((id) => w.nodes?.includes(id)));
        return { lat: g.lat, lon: g.lon, tags: g.tags, road: road?.tags ?? null, roadGeom: road?.geometry ?? null };
      })
    : RESEARCH.levelCrossings.map((/** @type {any} */ c) => ({ lat: c.lat, lon: c.lon, tags: { railway: c.type.includes('footpath') ? 'crossing' : 'level_crossing', 'crossing:barrier': c.type.includes('half') ? 'half' : c.type.includes('full') ? 'double_half' : '' }, road: { name: c.road, highway: c.type.includes('footpath') ? 'footway' : 'track' }, name: c.name }));
  for (const c of source) {
    const at = locate(P(c.lat, c.lon), 15);
    if (!at) continue;
    const hw = c.road?.highway ?? '';
    const barrier = c.tags['crossing:barrier'] ?? c.tags.barrier ?? '';
    let type;
    if (c.tags.railway === 'crossing' || /^(footway|path|steps|pedestrian)$/.test(hw)) type = hw === 'bridleway' ? 'BW' : 'FP';
    else if (hw === 'bridleway') type = 'BW';
    else if (barrier === 'half') type = 'AHB';
    else if (barrier === 'double_half' || barrier === 'full') type = 'MCB';
    else if (hw === 'track' || barrier === 'gate' || barrier === 'no' || !barrier) type = /^(primary|secondary|tertiary|unclassified|residential|trunk)$/.test(hw) ? 'MCB' : 'UWC';
    else type = 'MCB';
    const roadName = [c.road?.name, c.road?.ref].filter(Boolean).join(' ') || c.road?.prow_ref || '';
    // Prefer the crossing's own name from the research list (e.g. "Woodgate"), then the road's.
    const known = RESEARCH.levelCrossings.find((/** @type {any} */ r) => !r.name.startsWith('(') && Math.hypot((r.lat - c.lat) * 111000, (r.lon - c.lon) * 70000) < 40);
    const name =
      type === 'MCB' || type === 'AHB'
        ? known?.name ?? (roadName ? roadName.replace(/ [AB]\d+$/, '') : 'Level crossing')
        : type === 'UWC'
          ? 'Farm crossing'
          : roadName
            ? `${type === 'BW' ? 'Bridleway' : 'Footpath'} ${roadName}`
            : 'Footpath crossing';
    // Road geometry near the crossing, for drawing it.
    const road = c.roadGeom
      ? simplify(
          c.roadGeom.map((/** @type {any} */ g) => P(g.lat, g.lon)).filter((/** @type {[number, number]} */ p) => Math.hypot(p[0] - P(c.lat, c.lon)[0], p[1] - P(c.lat, c.lon)[1]) < 140),
          0.5,
        ).map(([x, y]) => [round(x), round(y)])
      : null;
    if (crossings.some((x) => x.line === at.line && Math.abs(x.position - at.s) < 15)) continue;
    crossings.push({
      id: `LC${crossings.length + 1}`,
      name,
      road: roadName,
      roadClass: hw,
      line: at.line,
      position: round(at.s),
      type,
      lights: c.tags['crossing:light'] === 'yes' || type === 'MCB' || type === 'AHB',
      whistle: type === 'FP' || type === 'BW' || type === 'UWC',
      ...(road && road.length >= 2 ? { roadPath: road } : {}),
    });
  }
  crossings.sort((a, b) => (a.line === b.line ? a.position - b.position : a.line.localeCompare(b.line)));
  crossings.forEach((c, i) => (c.id = `LC${String(i + 1).padStart(2, '0')}`));
  console.log(`level crossings: ${crossings.length} (${['MCB', 'AHB', 'FP', 'BW', 'UWC'].map((t) => `${crossings.filter((c) => c.type === t).length} ${t}`).join(', ')})`);
}

// ── signals ──────────────────────────────────────────────────────────────────

/**
 * Generate a plausible four-aspect layout (A): starting signals at platform ends, protecting
 * signals before full-barrier crossings, junction signals with feathers before facing points,
 * signals before each diamond and merge, then automatic signals so no section is longer than
 * about 1.7 km.
 */
function generateSignals() {
  /** @type {any[]} */
  const out = [];
  const lineIds = Object.keys(geo);
  const prefixFor = (/** @type {string} */ line, /** @type {number} */ s) => {
    if (line === 'bognor') return 'BR';
    if (line === 'littlehampton') return 'LH';
    if (line === 'coast') return 'AJ';
    const near = stations.filter((x) => x.line === 'main').sort((a, b) => Math.abs(a.position - s) - Math.abs(b.position - s))[0];
    return { CCH: 'CH', BAA: 'BN', FOD: 'FD', ARU: 'AL', AMY: 'AY' }[near.id] ?? 'WC';
  };
  for (const line of lineIds) {
    const len = lengthOf(line);
    for (const track of line === 'main' ? ['UP', 'DOWN'] : ['DOWN', 'UP']) {
      const dir = dirOf(line, track);
      const key = `${line}/${track}`;
      const u = (/** @type {number} */ s) => dir * s;
      const entry = dir > 0 ? 0 : len;
      const exit = dir > 0 ? len : 0;
      /** @type {{ s: number, kind: string, priority: number, feather?: any, approachControl?: boolean }[]} */
      const fixed = [];
      // Starting signals just beyond each platform's exit end, but before a crossing right there.
      for (const p of chosen.filter((x) => x.line === line && x.track === track)) {
        let s = (dir > 0 ? p.to : p.from) + dir * 12;
        const lc = crossings.find((c) => c.line === line && (c.type === 'MCB' || c.type === 'AHB') && u(c.position) > u(dir > 0 ? p.to : p.from) - 30 && u(c.position) - u(s) < 15);
        if (lc) s = lc.position - dir * 12;
        if (u(s) < u(exit) - 30) fixed.push({ s, kind: 'starting', priority: 2 });
      }
      // Protecting signals for full-barrier crossings.
      for (const lc of crossings.filter((c) => c.line === line && c.type === 'MCB')) {
        const before = fixed.filter((f) => u(lc.position) - u(f.s) > 5 && u(lc.position) - u(f.s) < 700);
        if (before.length) {
          before.forEach((f) => f.kind === 'starting' || (f.kind = 'protecting'));
          continue;
        }
        const s = lc.position - dir * 160;
        if (u(s) > u(entry) + 50) fixed.push({ s, kind: 'protecting', priority: 3 });
      }
      // Junction signals before facing points; a feather for the diverging way.
      for (const pt of points.filter((x) => x.type === 'facing' && x.at.line === line && x.at.track === track)) {
        const known = DIVERGING[/** @type {keyof typeof DIVERGING} */ (pt.id)];
        const diverging = known ? { ...known, speedMph: known.state === 'R' ? JUNCTION_SPEEDS[/** @type {keyof typeof JUNCTION_SPEEDS} */ (pt.other.line)]?.mph ?? 40 : 30 } : divergingRoute(pt);
        const branchSpeed = lineDefs[/** @type {keyof typeof lineDefs} */ (pt.other.line)].speed[0].mph;
        const feather = { points: pt.id, state: diverging.state, side: diverging.side };
        // A platform starter just before the points is the junction signal (Barnham: the Down
        // starter carries the Bognor feather). Trains start from rest there, so no approach control.
        const starter = fixed.find((f) => f.kind === 'starting' && u(pt.at.position) - u(f.s) > 0 && u(pt.at.position) - u(f.s) < 400);
        if (starter) {
          starter.feather = feather;
          starter.priority = 4;
          continue;
        }
        const s = pt.at.position - dir * 230;
        fixed.push({ s, kind: 'junction', priority: 4, feather, approachControl: diverging.speedMph <= 40 || branchSpeed <= 40 });
      }
      // Signals before diamonds (another route crossing this track on the flat).
      for (const pt of points.filter((x) => x.crosses?.includes(key))) {
        // A signal already just before the diamond (Barnham's Down starter) protects it.
        if (fixed.some((f) => u(pt.at.position) - u(f.s) > 0 && u(pt.at.position) - u(f.s) < 400)) continue;
        const s = pt.at.position - dir * 200;
        fixed.push({ s, kind: 'controlled', priority: 3 });
      }
      // Branch tracks joining the main line: a signal before the merge.
      if (dir < 0 && line !== 'main') fixed.push({ s: 180, kind: 'controlled', priority: 3 });
      // Tidy: inside the line, at least 120 m apart (keep the most important).
      const tidy = [];
      for (const f of fixed.filter((x) => x.s > 20 && x.s < len - 20).sort((a, b) => b.priority - a.priority)) {
        if (tidy.every((t) => Math.abs(t.s - f.s) >= 120)) tidy.push(f);
      }
      tidy.sort((a, b) => u(a.s) - u(b.s));
      // Fill gaps with automatic signals (target ≤ 1.7 km sections).
      const anchors = [{ s: entry }, ...tidy, { s: exit }];
      const all = [...tidy];
      for (let i = 0; i < anchors.length - 1; i++) {
        const a = anchors[i].s;
        const b = anchors[i + 1].s;
        const gap = Math.abs(b - a);
        const n = Math.ceil(gap / 1650) - 1;
        for (let k = 1; k <= n; k++) {
          const s = a + ((b - a) * k) / (n + 1);
          if (s > 60 && s < len - 60) all.push({ s, kind: 'auto', priority: 1 });
        }
      }
      all.sort((a, b) => u(a.s) - u(b.s));
      for (const sig of all) out.push({ line, track, position: round(sig.s), kind: sig.kind, ...(sig.feather ? { feather: sig.feather } : {}), ...(sig.approachControl ? { approachControl: true } : {}) });
    }
  }
  // Number them: area prefix, Up odd and Down even, in order along each line.
  /** @type {Map<string, number>} */
  const counters = new Map();
  out.sort((a, b) => (a.line === b.line ? a.position - b.position : a.line.localeCompare(b.line)));
  for (const sig of out) {
    const prefix = prefixFor(sig.line, sig.position);
    const up = sig.track === 'UP';
    const k = `${prefix}${up}`;
    const n = (counters.get(k) ?? (up ? -1 : 0)) + 2;
    counters.set(k, n);
    sig.id = `${prefix}${n}`;
    sig.aspects = '4';
  }
  return out;
}

/**
 * The diverging (turnout) route at each junction, from the OSM track layout: the Bognor branch
 * leaves the Down main to the left at Barnham; the Littlehampton curve leaves the Up main to the
 * right at Ford Junction; at Arundel Junction the Arun Valley line (our main line) is the one
 * that turns off, to the left, while the coast line runs straight on.
 */
const DIVERGING = Object.freeze({
  'BJ-D': { state: 'R', side: 'left' },
  'FJ-U': { state: 'R', side: 'right' },
  'AJ-U': { state: 'N', side: 'left' },
});

/**
 * Which way at a set of facing points is the diverging route (the one that turns more), its
 * side, and its speed.
 * @param {any} pt
 */
function divergingRoute(pt) {
  const main = geo[pt.at.line];
  const other = geo[pt.other.line];
  const dir = dirOf(pt.at.line, pt.at.track);
  const here = pointAlong(main.pts, main.cum, pt.at.position);
  // Judge "straight on" by the direction trains approach from, not the track at the points
  // (the main line may already be curving away there, as at Arundel Junction).
  const approach = pointAlong(main.pts, main.cum, pt.at.position - dir * 250);
  const heading = [approach.t[0] * dir, approach.t[1] * dir];
  const turn = (/** @type {[number, number]} */ p) => {
    const v = [p[0] - here.p[0], p[1] - here.p[1]];
    const len = Math.hypot(v[0], v[1]);
    const cross = heading[0] * v[1] - heading[1] * v[0];
    return { angle: Math.abs(Math.asin(Math.max(-1, Math.min(1, cross / len)))), side: cross > 0 ? 'left' : 'right' };
  };
  const straight = turn(pointAlong(main.pts, main.cum, pt.at.position + dir * 350).p);
  const branchTurn = turn(pointAlong(other.pts, other.cum, 350).p);
  const mainSpeed = lineDefs.main.speed.find((s) => s.from <= pt.at.position + dir * 100 && s.to >= pt.at.position + dir * 100)?.mph ?? 75;
  const branchSpeed = lineDefs[/** @type {keyof typeof lineDefs} */ (pt.other.line)].speed[0].mph;
  return branchTurn.angle >= straight.angle
    ? { state: 'R', side: branchTurn.side, speedMph: branchSpeed }
    : { state: 'N', side: straight.side, speedMph: mainSpeed };
}

const signals = generateSignals();
console.log(`signals: ${signals.length} (${signals.filter((s) => s.feather).length} junction signals with feathers)`);

// ── scenery ──────────────────────────────────────────────────────────────────

/** Elevation grid for the terrain, as Int16 decimetres. */
function terrainGrid() {
  const all = Object.values(geo).flatMap((g) => g.pts);
  const margin = 3500;
  const spacing = 75;
  const minX = Math.min(...all.map((p) => p[0])) - margin;
  const maxX = Math.max(...all.map((p) => p[0])) + margin;
  const minY = Math.min(...all.map((p) => p[1])) - margin;
  const maxY = Math.max(...all.map((p) => p[1])) + margin;
  const nx = Math.ceil((maxX - minX) / spacing) + 1;
  const ny = Math.ceil((maxY - minY) / spacing) + 1;
  const data = new Int16Array(nx * ny);
  for (let j = 0; j < ny; j++) {
    for (let i = 0; i < nx; i++) {
      const [lat, lon] = proj.unproject(minX + i * spacing, minY + j * spacing);
      data[j * nx + i] = Math.round((dem.height(lat, lon) ?? 0) * 10);
    }
  }
  return { header: { x0: round(minX), y0: round(minY), spacing, nx, ny, units: 'decimetres, Int16 little-endian, row-major from south-west' }, data };
}

/** Polygons from closed ways, simplified and projected. */
function polygons(/** @type {any[]} */ els, tolerance = 2) {
  /** @type {[number, number][][]} */
  const out = [];
  for (const e of els) {
    if (e.type !== 'way' || !e.geometry || e.geometry.length < 4) continue;
    const pts = simplify(e.geometry.map((/** @type {any} */ g) => P(g.lat, g.lon)), tolerance).map(([x, y]) => /** @type {[number, number]} */ ([round(x), round(y)]));
    if (pts.length >= 4) out.push(pts);
  }
  return out;
}

const woods = polygons(layer('woods'), 6).filter((p) => area(p) > 2000);
const water = layer('water');
const riverAreas = polygons(water.filter((e) => e.tags?.natural === 'water'), 3);
const riverLines = water
  .filter((e) => e.tags?.waterway === 'river' && e.geometry)
  .map((e) => simplify(e.geometry.map((/** @type {any} */ g) => P(g.lat, g.lon)), 3).map(([x, y]) => [round(x), round(y)]));

/** Not buildings we can extrude: platform canopies and roofs are drawn with the platforms. */
const NOT_BUILDINGS = /^(roof|canopy|carport|bridge|construction|no)$/;
/** Which side of the line a track's platforms are on (−1 left, +1 right of increasing chainage). */
const platformSide = (/** @type {string} */ line, /** @type {string} */ track) => ((line === 'main') === (track === 'UP') ? -1 : 1);

/**
 * Footprints that would stand on the track or on a platform (OSM often maps the station roof or
 * a canopy as a building, which extruded becomes a wall across the platform).
 * @param {[number, number][]} pts
 */
function encroaches(pts) {
  if (!pts.some((p) => locate(p, 60))) return false;
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i];
    const b = pts[(i + 1) % pts.length];
    const n = Math.max(1, Math.ceil(dist(a, b) / 3));
    for (let k = 0; k <= n; k++) {
      const hit = locate([a[0] + ((b[0] - a[0]) * k) / n, a[1] + ((b[1] - a[1]) * k) / n], 9);
      if (!hit) continue;
      if (hit.d < 4.5) return true;
      if (chosen.some((p) => p.line === hit.line && hit.s >= p.from - 10 && hit.s <= p.to + 10 && Math.sign(hit.lateral) === platformSide(p.line, p.track))) return true;
    }
  }
  return false;
}

let dropped = 0;
const buildings = layer('buildings')
  .filter((e) => e.type === 'way' && e.geometry && e.geometry.length >= 4 && !NOT_BUILDINGS.test(e.tags?.building ?? ''))
  .filter((e) => {
    const bad = encroaches(e.geometry.map((/** @type {any} */ g) => P(g.lat, g.lon)));
    if (bad) dropped++;
    return !bad;
  })
  .map((e) => {
    const pts = simplify(e.geometry.map((/** @type {any} */ g) => P(g.lat, g.lon)), 0.6).slice(0, -1);
    const t = e.tags ?? {};
    const levels = parseFloat(t['building:levels']);
    const kind = t.building;
    let h = parseFloat(t.height) || (levels ? levels * 3 + 1.5 : kind === 'church' || kind === 'cathedral' ? 16 : /^(industrial|warehouse|retail|commercial|supermarket)$/.test(kind) ? 8 : /^(garage|garages|shed|hut)$/.test(kind) ? 3 : 7.5);
    h = Math.min(60, h);
    const colour = /^(industrial|warehouse|retail|commercial|supermarket)$/.test(kind) ? 2 : kind === 'church' || kind === 'cathedral' ? 3 : /^(garage|garages|shed|hut)$/.test(kind) ? 1 : 0;
    return [round(h), colour, ...pts.flatMap(([x, y]) => [round(x), round(y)])];
  })
  .filter((b) => b.length >= 8);

const roads = layer('roads')
  .filter((e) => e.type === 'way' && e.geometry)
  .map((e) => {
    const cls = { motorway: 4, trunk: 4, primary: 3, secondary: 3, tertiary: 2, unclassified: 1, residential: 1 }[/** @type {string} */ (e.tags?.highway)] ?? 1;
    return [cls, ...simplify(e.geometry.map((/** @type {any} */ g) => P(g.lat, g.lon)), 2).flatMap(([x, y]) => [round(x), round(y)])];
  });

const landmarks = layer('landmarks')
  .filter((e) => e.tags?.name && (e.center || e.lat))
  .map((e) => {
    const c = e.center ?? e;
    const [x, y] = P(c.lat, c.lon);
    const kind = e.tags.historic === 'castle' ? 'castle' : 'cathedral';
    return { name: e.tags.name, kind, x: round(x), y: round(y) };
  })
  .filter((l, i, all) => all.findIndex((m) => m.name === l.name) === i);

/** Tree-lined stretches: slippery in autumn. */
function leafZones() {
  /** @type {{ line: string, from: number, to: number }[]} */
  const zones = [];
  for (const [id, g] of Object.entries(geo)) {
    let start = -1;
    for (let s = 0; s <= lengthOf(id); s += 50) {
      const { p } = pointAlong(g.pts, g.cum, s);
      const wooded = woods.some((poly) => {
        if (inPolygon(p, poly)) return true;
        return poly.some((q) => Math.hypot(q[0] - p[0], q[1] - p[1]) < 40);
      });
      if (wooded && start < 0) start = s;
      if (!wooded && start >= 0) {
        if (s - start >= 150) zones.push({ line: id, from: start, to: s });
        start = -1;
      }
    }
  }
  return zones;
}

// ── assemble, time, write ────────────────────────────────────────────────────

const route = {
  id: 'west-sussex',
  name: 'West Sussex: Chichester – Amberley',
  description: 'The West Coastway from Chichester through Barnham and Ford, over the River Arun to Arundel Junction, then up the Arun Valley line through Arundel to Amberley. Branches to Bognor Regis and Littlehampton.',
  version: 2,
  generated: new Date().toISOString().slice(0, 10),
  attribution: 'Track, stations, crossings and scenery © OpenStreetMap contributors (ODbL). Terrain: Mapzen/Tilezen terrain tiles (SRTM, EU-DEM). Signals, gradients and timetables are generated: see docs/ASSUMPTIONS.md.',
  origin: ORIGIN,
  units: { position: 'metres of chainage from the start of each line', speed: 'mph', gradient: 'per-mille' },
  lines,
  points,
  signalling: { overlapM: 180 },
  signals,
  stations,
  platforms: chosen,
  levelCrossings: crossings,
  leafZones: leafZones(),
  services: [],
  traffic: [],
  scenery: {
    seed: 2026,
    terrain: 'terrain.bin',
    sceneryFile: 'scenery.json',
    landmarks,
  },
};

if (process.env.DUMP_ROUTE) writeFileSync(process.env.DUMP_ROUTE, JSON.stringify(route));
const { services, traffic } = timetableServices(route);
route.services = services;
route.traffic = traffic;

mkdirSync(OUT, { recursive: true });
const terrain = terrainGrid();
route.scenery.terrainHeader = terrain.header;
writeFileSync(join(OUT, 'terrain.bin'), Buffer.from(terrain.data.buffer));
writeFileSync(join(OUT, 'scenery.json'), JSON.stringify({ woods, riverAreas, riverLines, buildings, roads }));
writeFileSync(join(OUT, 'route.json'), JSON.stringify(route, null, 1));
const kb = (/** @type {string} */ f) => `${Math.round(readFileSync(join(OUT, f)).length / 1024)} kB`;
console.log(`wrote route.json (${kb('route.json')}), terrain.bin (${kb('terrain.bin')}, ${terrain.header.nx}×${terrain.header.ny}), scenery.json (${kb('scenery.json')}: ${buildings.length} buildings (${dropped} on the track or platforms left out), ${roads.length} roads, ${woods.length} woods)`);
if (!existsSync(join(OUT, 'route.json'))) process.exit(1);
